import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';
import React, {useContext, useEffect, useState} from 'react';
import { stocks, categories, hoursList} from '../../models/contants/contants';
import IStockLookup from '../../models/common/lookup';
import ILookup from '../../models/common/lookup';
import { AlertChannelType, AlertStockFilterType, IAlert, IAlertChannelRow } from '../../models/alert/alert';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import toast, { Toaster } from 'react-hot-toast';
import * as utility from '../../utility/utility';
import { useNavigate, useParams } from 'react-router-dom';
import { muiTheme1 } from '../common/muicomp';
import { AuthContextType, AuthContext } from '../../auth/authContext';
import AlertChannelRow from './alertChannelRow';
import { ThemeProvider } from '@emotion/react';
import { useSelector } from 'react-redux';
import { RootState } from '../../redux/store';
import { IStock } from '../../models/stock/stock';

const Alert = () => {
     const { items: stocksData } = useSelector((state: RootState) => state.stocks);
  const navigate = useNavigate();
 const { user, isUserLoggedIn } = useContext<AuthContextType|null>(AuthContext)!;
  const [showLoading,setShowLoading] = useState<boolean>(false);
  const params= useParams();
  const [smsChannel, setSMSChannel] = useState("");
  const [alertChannelRows, setAlertChannelRows] = useState<IAlertChannelRow[]|[]>();
  const [alert, setAlert] = useState<IAlert>(
    {
      alertKey:'',
      name:'',
      stockFilterType: AlertStockFilterType.stock,
      userId :'test',
      smsChannels: [],
      whatsappChannels:[],
      emailChannels:[],
      digestEmailChannels:[],
      stockCodes:[],
      categoryCodes:[]
    });

    const loadAlert = async (alertKey:string) => {
      setShowLoading(true);
              await axios({
                  url: backend+'alerts/'+alertKey,
                  method: "Get",
                  headers: {
                      authorization: 'Bearer '+await user?.getIdToken()
                  }
              })
                  .then((res) => {
                      const data: IAlert = res.data;
                      setAlert(data);
                      setAlertChannelRowsData(data);
                  })
                  .catch((err) => {
                    window.alert('unable to get alert details')
                    navigate('/alerts');
                  }).finally(()=>{
                    setShowLoading(false);
                  });
          }
 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      if(params && params["alertkey"]){
        loadAlert(params["alertkey"]);
      }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[]);

    const setAlertChannelRowsData = (alert:IAlert) =>{
      const alertChannelRows:IAlertChannelRow[] = [];
      alert.smsChannels?.forEach(a => 
        alertChannelRows.push({channel:a,channelType:AlertChannelType.sms,isEdit:false, isNew:false})
      );
       alert.whatsappChannels?.forEach(a => 
        alertChannelRows.push({channel:a,channelType:AlertChannelType.whatsapp,isEdit:false,isNew:false})
      );
       alert.emailChannels?.forEach(a => 
        alertChannelRows.push({channel:a,channelType:AlertChannelType.email,isEdit:false,isNew:false})
      );
       alert.digestEmailChannels?.forEach(a => {
        const splits = a.split("|");
        alertChannelRows.push({channel:splits[0],channelType:AlertChannelType.digestemail,isEdit:false,isNew:false,
          freqType:splits[1],freqDays:splits[2].split(','),freqHour:splits[3],
        });
        return;
    });
      setAlertChannelRows(alertChannelRows);
    }

    const setAlertChannelData = () =>{
      const smsChannels = alertChannelRows!.filter(a => a.channelType === AlertChannelType.sms).map(a => a.channel);
      const whatsappChannels = alertChannelRows!.filter(a => a.channelType === AlertChannelType.whatsapp).map(a => a.channel);
      const emailChannels = alertChannelRows!.filter(a => a.channelType === AlertChannelType.email).map(a => a.channel);
      const digestEmailChannels = alertChannelRows!.filter(a => a.channelType === AlertChannelType.digestemail).map(a => a.channel+"|"+a.freqType+"|"+a.freqDays?.join(',')+"|"+a.freqHour);
      alert.smsChannels = smsChannels;
      alert.whatsappChannels = whatsappChannels;
      alert.emailChannels = emailChannels;
      alert.digestEmailChannels = digestEmailChannels;
    }

    const validateSaveAlert = () => {
      var isvalid = true;
      if(utility.isNullEmptyOrWhitespace(alert.name)){
        toast.error('invalid alert name');
        isvalid = false;
      }

      if(alert.stockCodes.length === 0 && alert.categoryCodes.length === 0){
        toast.error('select stocks or categories');
        isvalid = false;
      }

      if(alert.smsChannels.length === 0 && alert.whatsappChannels.length === 0 && alert.emailChannels.length === 0){
        toast.error('select alert notification channels');
        isvalid = false;
      }

      return isvalid;
    }
    const saveAlert = async  (event:any) =>{
      if(!isUserLoggedIn()){
        toast.error('Login to create alerts.');
        return;
      }
      debugger;
      setAlertChannelData();
      if(!validateSaveAlert()){
        return;
      }
      
      await axios({
        // Endpoint to send files
        url: backend+"alerts",
        method: "Post",
        headers: {
            // Add any auth token here
            authorization: 'Bearer '+await user?.getIdToken()
        },

        // Attaching the form data
        data: alert,
    })
        // Handle the response from backend here
        .then((res) => {
          toast.success('alert saved');
            window.location.href = '#/alerts';
        })
        .catch((err) => {});
    }

    const cancelAlert = async  (event:any) =>{
      window.location.href = '#/alerts';
    }
    // const onSectorsChange = (event:any, values:ILookup[]) => {
    //     //setAnnoncementRequest({...annnouncementRequest, stockcodes: values.map(a=> a.code)});
    // } 
    const onFilterStocksChange = (event:any, values:ILookup[]) => {
      setAlert({...alert, stockCodes: values.map(a=> a.code)});
    } 

    const onCategoriesChange = (event:any, values:ILookup[]) => {
        setAlert({...alert, categoryCodes: values.map(a => a.code)});
    } 

    const deleteChannel = (index:number) =>{
     const newArr = alertChannelRows?.filter((a,i)=> index !== i);
     setAlertChannelRows(newArr);
    }

    const onSaveChannelEvent = (index:number, channel:string, channelType:AlertChannelType,freqType:string,freqDays:string[],freqHour:string)  => {
        setAlertChannelRows((prevItems: any) => 
          prevItems.map((item:IAlertChannelRow, i:number) => 
            i === index ? { ...item, channel: channel, channelType: channelType,isNew:false,isEdit:false,freqType:freqType, freqDays:freqDays,freqHour:freqHour } : item
          )
        );
    }

    const onCancelNewRecord = () =>{
      setAlertChannelRows(alertChannelRows?.filter(a => !a.isNew));
    }

    const addChannel = () => {
       setAlertChannelRows([...alertChannelRows || [], {channel:'', channelType: AlertChannelType.email , isEdit:true, isNew:true}]);
    }

    const disableSave = () =>{
      if(alertChannelRows && alertChannelRows?.filter(a => a.isNew).length > 0) return true;
      if(utility.isNullEmptyOrWhitespace(alert.name)) return true;
      if(alert.stockCodes.length === 0 && alert.categoryCodes.length === 0) return true;
      if(!alertChannelRows || alertChannelRows!.length === 0) return true;
      return false;
    }

    const enableAddChannel = () =>{
      var enabled = true;
      if(alertChannelRows && alertChannelRows!.filter(a => a.isNew).length > 0)
        enabled = false;

      return enabled;
    }
    const getPageHeader = () =>{
      if(params["alertkey"]){
return "Edit Alert"
      }else{
return "Create Alert"
      }
    }

    return (
      <div>
        {/* 📢  */}
        <Toaster position="bottom-center" reverseOrder={false}/>
        <div className='page-header'>
        <div>
        <ol className="breadcrumb bg-transparent mb-0 pb-0 pt-1 px-0 me-sm-6 me-5">
              <li className="breadcrumb-item"><a className='link font-weight-bold' href="#/alerts">
              <svg className="mb-2px" xmlns="http://www.w3.org/2000/svg" height="18px" viewBox="0 -960 960 960" width="18px" fill="currentColor"><path d="m456-200 174-340H510v-220L330-420h126v220Zm24 120q-83 0-156-31.5T197-197q-54-54-85.5-127T80-480q0-83 31.5-156T197-763q54-54 127-85.5T480-880q83 0 156 31.5T763-763q54 54 85.5 127T880-480q0 83-31.5 156T763-197q-54 54-127 85.5T480-80Zm0-80q134 0 227-93t93-227q0-134-93-227t-227-93q-134 0-227 93t-93 227q0 134 93 227t227 93Zm0-320Z"/></svg>
         
              &nbsp; Alerts</a></li>
              <li className="breadcrumb-item text-header active" aria-current="page"><strong>
                <span>{getPageHeader()}</span></strong>
                </li>
                <li></li>
                </ol>
                {!isUserLoggedIn() && <a href='#/signin' className="link text-xs ml-5 text-warning">! Login to create alerts</a>}
            </div>
        </div>
<div className='content-margin'>
<div className="card col-md-12">
            { !showLoading && <ThemeProvider theme={muiTheme1}>
               <div className="card-body">
               <div className='row'>
                   <div className='col mb-3'>
                   <TextField 
                    value={alert.name} 
                    onChange={(e) =>{
                      setAlert({...alert, name: e.target.value});
                     }
                   }
                   id="outlined-basic" label="alert name" 
                   variant="outlined" />
                   </div>
             </div>
               <div className="form-floating mb-3">
               <Autocomplete  
                 value={stocksData.filter(a => alert.stockCodes.filter(b => b === a.code).length > 0)}
                 onChange={onFilterStocksChange}
                 multiple
                 options={stocksData}
                 getOptionLabel={(option:IStock) => option.code+' - '+option.name}
                 renderInput={(params) => (
                   <TextField {...params} label="filter stocks" placeholder="Search by scrip code or name" />
                 )}
               />
           </div>
           
           <div className="row mb-3">
             <Autocomplete
                 value={categories.filter(a => alert.categoryCodes.filter(b => b === a.code).length > 0)}
                 multiple
                 id=""
                 onChange={onCategoriesChange}
                 options={categories}
                 getOptionLabel={(option:ILookup) => option.name}
                 renderInput={(params) => (
                   <TextField {...params} label="category" placeholder="Select Categories" />
                 )}
               />
           </div>
           <div className="card">
                   <div className="card-header pb-0 p-3">
                         <div className="row mb-3">
                         <div className="col-6 d-flex align-items-center">
                             <h6 className="mb-0">Alerting Channels</h6>
                           </div>
                           <div className="col-6 text-end">
                             <button disabled={!enableAddChannel()} onClick={addChannel} className="btn btn-success btn-sm mb-0">+ Add Channel&nbsp;
                              </button>
                           </div>
                         </div>
                       </div>
                       <div className="card-body pt-0">
 <div className="card-body table-responsive px-0 pb-2">
             <table className="table align-items-center mb-0">
               <thead>
                 <tr>
                   <th>
                   <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Channel type</div>
                   </th>
                   <th>
                   <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Channel</div>
                   </th>
                   <th>
                   <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Actions</div>
                   </th>
                 </tr>
               </thead>
               <tbody>
              {alertChannelRows?.map((row,idx) => 
                <AlertChannelRow onCancelNewRecord={onCancelNewRecord} onSaveChannel={onSaveChannelEvent} onDeleteChannel={deleteChannel} 
                 index={idx} isNew={row.isNew} channel={row.channel} type={row.channelType} isEdit={row.isEdit}
                 freqType={row.freqType} freqDays={row.freqDays} freqHour={row.freqHour}/>
              )}
               </tbody> 
             </table>
           </div>
           </div>
                   </div>
           <div className="text-right pt-3">
           <button  disabled={disableSave()} type='button' onClick={saveAlert} className="btn btn-success btn-sm mb-0 mr-2 ">
           <span className="material-symbols-rounded text-sm ">
           check
           </span>
           &nbsp;Save</button>
           <button type='button' onClick={cancelAlert} className="btn btn-danger btn-sm mb-0 ml-7">
           <span className="material-symbols-rounded text-sm">
           close
           </span>
           &nbsp;Cancel</button>
           </div>
                 
               </div>
               </ThemeProvider>}
                   </div>
</div>

        
        </div>
    ) 
}

export default Alert;


