// features/stocks/stocksSlice.ts
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import axios from 'axios';
import { IStock } from '../../models/stock/stock';
import { backend } from '../../models/contants/contants';
import IAnnouncement, { AnnouncementImpression } from '../../models/announcement/announcement';
import IAnnouncementRequest from '../../models/announcement/announcementRequest';

interface AnnouncementsState {
  items: IAnnouncement[];
  announcementReq: IAnnouncementRequest;
  loading: boolean;
  error: string | null;
}

 var fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - 1);
    
export const initialState: AnnouncementsState = {
  items: [],
  announcementReq: {
          stockcodes: [],
          categories:[],
          impressions:[AnnouncementImpression.positive],
          fromDate: fromDate,
          toDate: new Date()},
  loading: false,
  error: null,
};

export const fetchAnnouncements = createAsyncThunk<
  IAnnouncement[],                         // return type
  IAnnouncementRequest,              // argument type
  { rejectValue: string }                  // optional error type
>(
  'stocks/fetchAnnouncements',
  async (payload, { rejectWithValue }) => {
    try {
      const response = await axios.post(`${backend}announcements`, payload, {
        headers: {
          authorization: 'your token here',
        },
      });
      return response.data;
    } catch (err: any) {
      return rejectWithValue(err.message);
    }
  }
);

const announcementsSlice = createSlice({
  name: 'announcements',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchAnnouncements.pending, (state, action) => {
        state.loading = true;
        state.error = null;
        state.announcementReq = action.meta.arg;
      })
      .addCase(fetchAnnouncements.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload;
      })
      .addCase(fetchAnnouncements.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      });
  },
});

export default announcementsSlice.reducer;
