// components/stocks/Stocks.tsx
import React, { useEffect, useRef, useState } from 'react';
import { Box, CircularProgress, TextField } from '@mui/material';
import StockTable from './stocksTable';
import { useNavigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { useDispatch, useSelector } from 'react-redux';
import { AppDispatch, RootState } from '../../redux/store';
import { fetchStocks } from '../../redux/stock/stocksSlice';
const Stocks = () => {

  const dispatch = useDispatch<AppDispatch>();
  const [searchedVal, setSearchedVal] = useState('');

  const { items: stocks, loading } = useSelector((state: RootState) => state.stocks);

useEffect(() => {
  if (stocks.length === 0) {
    dispatch(fetchStocks());
  }
}, [dispatch, stocks.length]);

  const filteredStocks = stocks.filter(a=> {
      return a.code?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
       a.name?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
       a.sector?.toLocaleLowerCase().indexOf(searchedVal) > -1;
     });

  return (
    <div>
      <div className='page-header'>
        <div className='row'>
          <div className='col-6 align-items-center'>
            <div>
              <h6 className='mb-0'>Stocks</h6>
            </div>
            <small className='text-secondary'>found {filteredStocks.length} stocks</small>
          </div>
          <div className='col-6 text-end'>
            <TextField
              size='small'
              onChange={(e) => setSearchedVal(e.target.value.toLowerCase())}
              id='outlined-basic'
              placeholder='filter stocks'
              variant='outlined'
              label='filter stocks'
            />
          </div>
        </div>
      </div>

      <div className='table-responsive page-content'>
        <StockTable rows={stocks.filter(a=> {
             return a.code?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
              a.name?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
              a.sector?.toLocaleLowerCase().indexOf(searchedVal) > -1 ||
              a.isinNumber?.toLocaleLowerCase().indexOf(searchedVal) > -1;
            })}/>
      </div>

      <div className='text-center'>
        {loading && <CircularProgress className='spinner' />}
      </div>
    </div>
  );
};

export default Stocks;
