import dayjs from "dayjs";

export function isNullEmptyOrWhitespace(str:string) {
    return (str === null || str === undefined || typeof str !== 'string' || str.trim() === '');
}

export function validatePhoneNum(num:string){
    const regex = /^\+91[6-9]\d{9}$/;
    return regex.test(num);
}

export function validateEmail(email:string){
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
}

export function getColor(code:string){
    var firstLetter = code.substring(1,2);
    if(firstLetter >= 'A' && firstLetter <= 'G'){
        return 'deeppink'
    }else if(firstLetter >= 'H' && firstLetter <= 'N'){
        return 'darkgreen';
    }else if(firstLetter >= 'O' && firstLetter <= 'U'){
      return 'orangered';
    }else{
        return '#673ab7';
    }
}

export function strJoin(strings:string[]){
   var joinText = '';
   strings.map((val,i)=>{
    joinText += val;
    if(i < strings.length-1){
        if(i === strings.length-2)
            joinText += ' and ';
        else
        joinText +=', '
    }
    return val;
   });
   return joinText;
}

export function areDatesEqual(date1:Date, date2:Date) {
  return (
    date1.getFullYear() === date2.getFullYear() &&
    date1.getMonth() === date2.getMonth() &&
    date1.getDate() === date2.getDate()
  );
}

export function formatRecentTime(date: Date) {
    const now = new Date();
    const diffMs = +now - +date;
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    
    if (diffMins < 60) {
      return `${diffMins} minute${diffMins === 1 ? '' : 's'} ago`;
    }
    
    if (diffHours < 24) {
      return `${diffHours} hour${diffHours === 1 ? '' : 's'} ago`;
    }
    
    // For 24+ hours, you might want to show actual date
    return dayjs(date).format('ddd MMM D YYYY hh:mm a');
  }
