// services/AlertService.ts
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { IUserAlertQuota } from '../../models/quota/useralertquota';

  export const getUserAlertQuotas = async(token:any): Promise<IUserAlertQuota> => {
    try {
      const response = await axios({
        url: `${backend}quotas/alertquotas`,
        method: "GET",
        headers: {
          authorization: `Bearer ${token}`
        }
      });
      return response.data;
    } catch (error) {
      console.error('Error loading getUserAlertQuotas:', error);
      throw error; // Re-throw the error to let the component handle it
    }
  }
