export const UserAvatar = (userName:string|undefined|null,photoURL:string|null|undefined) =>{

    const getUserLetterAvatar = (name:string|undefined|null) =>{
        if(!name) return "";
        
        var splits = name.split(" ");
        if(splits.length > 1){
           return splits[0][0]+""+splits[1][0];
        }else{
            return name.substring(0,2);
        }
    }
    return (
        <>
        {photoURL && <img alt="" className='avatar avatar-xs mb-1' src={photoURL!}></img>}
        {!photoURL && <div className='avatar avatar-xs mb-1'>{getUserLetterAvatar(userName)}</div>}
      </>)}


 export const isCurrentPath = (path:string, pathname:string) => {
    if(path === "/"){
      return (pathname === path) || pathname.indexOf("/announcements") !== -1;
    } 
     return pathname.indexOf(path) !== -1;
  }
      
