const AlertHistoryTable = (props: IAlertHistoryTableProps)  => {
  
    const {
        rows
      } = props;

  const [page, setPage] = React.useState(0);
  const [rowsPerPage, setRowsPerPage] = React.useState(50);
  
  useEffect(() => {
}, [rows]);


  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Avoid a layout jump when reaching the last page with empty rows.
  const emptyRows =
    page > 0 ? Math.max(0, (1 + page) * rowsPerPage - rows.length) : 0;

  const visibleRows = React.useMemo(
    () =>
      [...rows]
        //.sort(getComparator(order, orderBy))
        .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage),
    [page, rowsPerPage, rows]
  );

  return (
    <div>
        <ThemeProvider theme={muiTheme}>
        <Table
          sx={{ minWidth: 750 }}
          aria-labelledby="tableTitle"
          size={'medium'}
        >
          <TableHead>
            <TableRow>
              <TableCell>
                <div className='text-uppercase text-primary text-xxs font-weight-bolder opacity-7'>Alert</div>
              </TableCell>
              <TableCell>
                <div className='text-uppercase text-primary text-xxs font-weight-bolder opacity-7'>Channel</div>
              </TableCell>
              <TableCell>
                <div className='text-uppercase text-primary text-xxs font-weight-bolder opacity-7'>Delivered On</div>
              </TableCell>
              <TableCell>
                <div className='text-uppercase text-primary text-xxs font-weight-bolder opacity-7'>Anouncement</div>
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
          

            {visibleRows.map((row, index) => {
              return (
                <TableRow
                  hover
                  key={row.alertKey}>
                  <TableCell align="left">
                  <p className="text-sm text-primary mb-0">
                    <a href={"#/alert/"+(row.alertKey)}>{row.alertName}</a>
                  </p>
                  </TableCell>
                    <TableCell align="left">
                  <p className="text-sm text-primary mb-0">
                   {row.userAlertChannelType === AlertChannelType.sms && <SMSIcon/>}
                    {row.userAlertChannelType === AlertChannelType.whatsapp && <WhatsappIcon/>}
                    {row.userAlertChannelType === AlertChannelType.email && <EmailIcon/>} &nbsp;
                    {row.channel}
                  </p>
                    </TableCell>
                    <TableCell align="left">
                  <p className="text-sm text-primary mb-0">
                   {dayjs(row.deliveredOn).format("MMM D, YYYY h:mm A")}
                  </p>
                    </TableCell>
                  <TableCell align="left">
                     <a href={"#/announcements/"+(row.announcementKey)}>{row.announcementName}</a>
                  </TableCell>
                </TableRow>
              );
            })}
            {emptyRows > 0 && (
              <TableRow>
                <TableCell colSpan={6} />
              </TableRow>
            )}
          </TableBody>
        </Table>
      <TablePagination
        hidden={rows.length<rowsPerPage}
        rowsPerPageOptions={[5, 10, 25,50,100]}
        component="div"
        count={rows.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
      />
      </ThemeProvider>
    </div>
  );
}

function descendingComparator<T>(a: T, b: T, orderBy: keyof T) {
  if (b[orderBy] < a[orderBy]) {
    return -1;
  }
  if (b[orderBy] > a[orderBy]) {
    return 1;
  }
  return 0;
}

type Order = 'asc' | 'desc';

function getComparator<Key extends keyof any>(
  order: Order,
  orderBy: Key
): (
  a: { [key in Key]: number | string | Date },
  b: { [key in Key]: number | string | Date }
) => number {
  return order === 'desc'
    ? (a, b) => descendingComparator(a, b, orderBy)
    : (a, b) => -descendingComparator(a, b, orderBy);
}

