import axios from "axios";
import IAnnouncementRequest from "../../models/announcement/announcementRequest";
import IAnnouncement from "../../models/announcement/announcement";
import { backend } from "../../models/contants/contants";

const fetchAnnouncementsData = async (announcementReq: IAnnouncementRequest):Promise<IAnnouncement[]> => {
    var response: IAnnouncement[] = [];
    try {
       await axios({
            // Endpoint to send files
            url: backend+"announcements",
            method: "Post",
            data: announcementReq,
        })
            // Handle the response from backend here
            .then((res) => {
                response = res.data;
            })
            .catch((err) => {});
        return response;
    } catch (error) {
        throw(error);
    }
};

export { fetchAnnouncementsData };

