import React, {useEffect, useState} from 'react';
import axios from 'axios';
import { backend, categories } from '../../models/contants/contants';
import { useNavigate, useParams } from 'react-router-dom';
import IAnnouncement, { AnnouncementImpression, AnnouncementSource } from '../../models/announcement/announcement';
import dayjs from 'dayjs';
import AnnouncementsComp from './announcementComp';
import { Box, LinearProgress } from '@mui/material';
import { ImpressionBadge } from '../common/utilitycomp';
import IAnnouncementRequest from '../../models/announcement/announcementRequest';
import { fetchAnnouncementsData } from '../../services/announcement/announcementService';

const Announcement = () => {
    var fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - 89);

  const params= useParams();
  const [showLoading, setShowLoading] = useState<boolean>(false);
  const [showSearchLoading, setShowSearchLoading] = useState<boolean>(false);
  const [showAnnouncementsLoading, setShowAnnouncementsLoading] = useState<boolean>(false);
  const [announcement, setAnnoncement] = useState<IAnnouncement|undefined>(undefined);
  const [announcements, setAnnouncements] = useState<IAnnouncement[]>([]);
  const [announcementReq, setAnnouncementsReq] = useState<IAnnouncementRequest>({
        stockcodes: [],
        categories:[],
        impressions:[AnnouncementImpression.positive],
        fromDate: fromDate,
        toDate:new Date()
      });

    const loadAnnouncement = async (announcementKey:string) => {
      setShowLoading(true);
              await axios({
                  url: backend+'announcements/'+announcementKey,
                  method: "Get",
                  headers: {
                      authorization: "your token comes here",
                  }
              })
                  .then((res) => {
                      const data: IAnnouncement = res.data;
                      setAnnoncement(data);
                      loadAnnouncements(data.stockCode);
                  })
                  .catch((err) => {
                    //window.alert('unable to get alert details')
                  }).finally(()=>{
                    setShowLoading(false);
                  });
          }

          const loadAnnouncements = async (stockCode:string) => {
            setShowAnnouncementsLoading(true);
            const updatedReq = {...announcementReq, stockcodes: [stockCode]};
            setAnnouncementsReq(updatedReq);
            const announcements = await fetchAnnouncementsData(updatedReq);
            setAnnouncements(announcements);
            setShowAnnouncementsLoading(false);
          }

 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
       window.scrollTo(0, 0);
        if(params && params["announcementKey"]){
          loadAnnouncement(params["announcementKey"]);
        }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[params]);

      const search = async (inputReq:IAnnouncementRequest) => {
        setShowSearchLoading(true);
        const announcements = await fetchAnnouncementsData(inputReq);
        setAnnouncements(announcements);
         setShowSearchLoading(false);
      }

    // const headerName = announcement?.stockCode+"'s Other Announcements";
    return (
      <div>
       { announcement && 
       <>
       <div className='page-header'>
       <ol className="breadcrumb bg-transparent mb-0 pb-0 pt-1 px-0 me-sm-6 me-5">
              <li className="breadcrumb-item"><a className='link font-weight-bold' href="#/announcements">
              <svg className="mb-2px mr-5" xmlns="http://www.w3.org/2000/svg" height="18px" viewBox="0 -960 960 960" width="18px" fill="currentColor"><path d="M640-440v-80h160v80H640Zm48 280-128-96 48-64 128 96-48 64Zm-80-480-48-64 128-96 48 64-128 96ZM120-360v-240h160l200-200v640L280-360H120Zm280-246-86 86H200v80h114l86 86v-252ZM300-480Z"/></svg>
        
               Annoucements</a></li>
              <li className="breadcrumb-item text-header active" aria-current="page"><strong>
                <span>{announcement.stockName}</span></strong></li></ol>
       </div>
       <div className='content-margin'>
        <div className='card mb-3'>
<div className='card-body'>
<ul className="list-group mb-3">
                  <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Company:</strong> &nbsp; {announcement.stockName} (#{announcement.stockCode})</li>
                    <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Category:</strong> &nbsp; 
                    <span className='badge bg-success-subtle text-success'>{categories.filter(a => a.code === announcement.category)[0].name}</span></li>
                    <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Summary 
                    { announcement.aiSummary && <img alt="AI" title="AI generated summary" className="text-sm avatar-img-sm ml-5 mr-2" src="https://cdn-icons-png.flaticon.com/128/9078/9078604.png"/>}
                       :
                   
                      </strong> &nbsp; {announcement.aiSummary ?? announcement.subject} 
                      
                      </li>
                 
                    <li className="list-group-item border-0 ps-0"><strong className="text-dark">Announcement Date:</strong> &nbsp; {dayjs(announcement.announcementDate).format("MMM D, YYYY h:mm A")}</li>
                    <li className="list-group-item border-0 ps-0"><strong className="text-dark">Exchange:</strong> &nbsp;
                    
                    {announcement.source === AnnouncementSource.nse && <img height={13} style={{marginTop:-3}} src='https://www.nseindia.com/assets/images/NSE_Logo.svg' alt="bse"></img>}
                    
                     {announcement.source === AnnouncementSource.bse && <img height={20} style={{marginTop:-13}} src='https://logos-world.net/wp-content/uploads/2023/07/BSE-Logo-500x281.png' alt="bse"></img>}
                     
                      </li>
                    <li className="list-group-item border-0 ps-0">
                      <strong className="text-dark">Announcement PDF:</strong> &nbsp; <a className="link" target='blank' href={announcement.url}>
                      pdf url <i className="material-symbols-rounded text-sm me-2">open_in_new</i></a></li>
                    <li className="list-group-item border-0 ps-0"><strong className="text-dark">Impression:</strong> &nbsp; 
                    {ImpressionBadge(announcement.impression)}
                    </li>
                  </ul>
                  <div className="card bg-primary">
                <div>
                  <AnnouncementsComp useStateData={false} 
                  inputRequest={announcementReq}  isSingleStockView={true}>
                  </AnnouncementsComp>
            </div>
        </div>
    </div>
        </div>
       </div>
      </>
      }
</div>

)}

export default Announcement;
