import { Select, MenuItem, TextField, OutlinedInput } from '@mui/material';
import * as React from 'react';
import { AlertChannelType } from '../../models/alert/alert';
import ILookup from '../../models/common/lookup';
import { hoursList } from '../../models/contants/contants';
import { WhatsappIcon, EmailIcon, SMSIcon, DigestEmailIcon } from '../common/utilitycomp';
import toast from 'react-hot-toast';
import * as utility from '../../utility/utility';

const AlertChannelRow = (props: any)  => {
    
    const {
        index,
        isNew,
        isEdit,
        type,
        channel,
        freqType,
        freqDays,
        freqHour
      } = props;
    //const digestFreqSplits = channel.split('|');
    const [showValueError, setShowValueError] = React.useState(false);
    const [isEditRecord, setIsEditRecord] = React.useState(isEdit);
    const [channelType, setChannelType] = React.useState(type);
    const [channelValue, setChannelValue] = React.useState(channel);
    const [digestFreqType, setDigestFreqType] = React.useState(freqType || 'daily');
    const [digestFreqDays, setDigestFreqDays] = React.useState<string[]>(freqDays || ['sat']);
    const [digestFreqHour, setDigestFreqHour] = React.useState(freqHour || '6:00am');
    //const [channelLabel, setChannelLabel] = React.useState("");

    const channelLabel = () =>{
      if(channelType === AlertChannelType.sms || channelType === AlertChannelType.whatsapp ){
        return "phone number with country code";
      }else{
        return "email address";
      }
    }
    const deleteChannel = () =>{
      if(window.confirm('are you sure want to delete?')){
       props.onDeleteChannel(index);
      }
    }

     const edit = () =>{
      setIsEditRecord(!isEditRecord);
    }

    const cancel = () =>{
      if(isNew){
        props.onCancelNewRecord();
      }else{
        setIsEditRecord(!isEditRecord);
      }
    }

    const save = (channel:string, channelType:AlertChannelType, prevChannel:string, prevChannelType:AlertChannelType,
      freq:string,freqDays:string[],freqHour:string
    ) =>{
      
      if(validate()){
        //setShowValueError(false);
        setIsEditRecord(!isEditRecord);
        props.onSaveChannel(index, channel, channelType,freq,freqDays,freqHour);
      }else{
        //setShowValueError(true);
      }
    }
    const validate = () => {
      debugger;
      if((channelType === AlertChannelType.sms || channelType === AlertChannelType.whatsapp) 
        && !utility.validatePhoneNum(channelValue)){
        toast.error('invalid phone number');
        return false;
      }else if((channelType === AlertChannelType.email || channelType === AlertChannelType.digestemail) 
        && !utility.validateEmail(channelValue)){
        toast.error('invalid email');
        return false;
      }
      return true;
    }

    const handleFreqDaysChange = (event:any) => {
    const {
      target: { value },
    } = event;
    setDigestFreqDays(
      typeof value === 'string' ? value.split(',') : value,
    );
  };
  return (
    
    <>
          {isEditRecord && <tr>
           <td>
             <Select
              size='small'
              value={channelType}
              label="channel"
              onChange={(e) => setChannelType(e.target.value)}
           >
              <MenuItem  value={AlertChannelType.sms}><SMSIcon/>&nbsp;{AlertChannelType.sms}</MenuItem>
             <MenuItem disabled value={AlertChannelType.whatsapp}><WhatsappIcon/>&nbsp;{AlertChannelType.whatsapp}</MenuItem>
             <MenuItem value={AlertChannelType.email}><EmailIcon/>&nbsp;&nbsp;{AlertChannelType.email}</MenuItem>
             <MenuItem value={AlertChannelType.digestemail}><DigestEmailIcon/>&nbsp;&nbsp;consolidated email alerts</MenuItem>
           </Select>

           </td>
           <td>
             <TextField 
             error = {showValueError}
             size='small'  
             helperText={showValueError ? "Invalid value":""}
             value={channelValue} onChange={(e) => {setChannelValue(e.target.value)}} 
             label={channelLabel()} placeholder={channelLabel()} variant="outlined" />

             { channelType === AlertChannelType.digestemail && <div className='mt-2'>
              <span className='font-weight-bold'>frequency: &nbsp;</span>
          <Select
             size='small'
             value = {digestFreqType}
             label="channel"
             onChange={(e) => setDigestFreqType(e.target.value)}
           >
             <MenuItem value="daily">daily</MenuItem>
             <MenuItem value="weekly">weekly</MenuItem>
           </Select> &nbsp;
          { digestFreqType === "weekly" && <Select
              size='small'
              multiple
              value={digestFreqDays}
              label="channel"
              input={<OutlinedInput label="Name" />}
              onChange={handleFreqDaysChange}
           >
             <MenuItem value="mon">monday</MenuItem>
             <MenuItem value="tue">tuesday</MenuItem>
              <MenuItem value="wed">wednesday</MenuItem>
             <MenuItem value="thu">thursday</MenuItem>
              <MenuItem value="fri">friday</MenuItem>
             <MenuItem value="sat">saturday</MenuItem>
              <MenuItem value="sun">sunday</MenuItem>
           </Select>}
           &nbsp;
           <Select
              size='small'
             value={digestFreqHour}
             label="channel"
             onChange={(e)=>setDigestFreqHour(e.target.value)}
           >
              {hoursList.map(( hour:ILookup ) => 
               {return <MenuItem value={hour.code}> {hour.name} </MenuItem>})}
           </Select>
           </div>}
           </td>
           <td>
           <button onClick={() => save(channelValue,channelType,channel,type, digestFreqType, digestFreqDays, digestFreqHour)} className="btn btn-link text-success text-gradient px-3 mb-0">
           <i className="material-symbols-rounded text-sm me-2">save</i>save</button>
           <button onClick={() => cancel()} className="btn btn-link text-danger text-gradient px-3 mb-0">
           <i className="material-symbols-rounded text-sm me-2">cancel</i>cancel</button>
           </td>
         </tr>}

         {!isEditRecord && <tr>
         
            <td>
             {props.type === AlertChannelType.sms && <SMSIcon/>}
              {props.type === AlertChannelType.whatsapp && <WhatsappIcon/>}
              {props.type === AlertChannelType.email && <EmailIcon/>}
              {props.type === AlertChannelType.digestemail && <DigestEmailIcon/>}
              &nbsp;&nbsp;{props.type}
              </td>
               <td>{props.channel}
                { props.type === AlertChannelType.digestemail &&  <> <div><span className='font-weight-bold'>frequency:&nbsp;</span>  {freqType} {freqDays} @{freqHour}</div></>}
               </td>

               <td>
          
           <button onClick={() => edit()} className="btn btn-link text-success text-gradient px-3 mb-0">
           <i className="material-symbols-rounded text-sm me-2">edit</i>edit</button>
            <button onClick={() => deleteChannel()} className="btn btn-link text-danger text-gradient px-3 mb-0">
           <i className="material-symbols-rounded text-sm me-2">delete</i>delete</button>
           </td>
          </tr>}
         </>
)
}

export default AlertChannelRow;
