import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs from 'dayjs';
import React, {useEffect, useState} from 'react';
import { stocks, categories, impressions } from '../../models/contants/contants';
import IAnnouncementRequest from '../../models/announcement/announcementRequest';
import IStockLookup from '../../models/common/lookup';
import ILookup from '../../models/common/lookup';
import IAnnouncement, { AnnouncementCategory, AnnouncementImpression } from '../../models/announcement/announcement';
import axios from 'axios';
import { Box, CircularProgress, LinearProgress, ThemeProvider } from '@mui/material';
import { backend } from '../../models/contants/contants';
import AnnouncementTableComponent from './announcementTableComponent';
import toast, { Toaster } from 'react-hot-toast';
import { muiTheme, muiTheme1 } from '../common/muicomp';
import { areDatesEqual, strJoin } from '../../utility/utility';
import AnnouncementTableComponentMobile from './announcementTableComponentMobile';
import {isMobile} from 'react-device-detect';
import { useDispatch, useSelector } from 'react-redux';
import { AppDispatch, RootState } from '../../redux/store';
import { fetchAnnouncements, initialState } from '../../redux/announcement/announcementSlice';
import { fetchAnnouncementsData } from '../../services/announcement/announcementService';
import { IStock } from '../../models/stock/stock';
import { IAnnouncementCompProps } from '../../models/announcement/announcementCompProps';
//import { fetchAnnouncements } from '../../services/announcement/announcementService';

const AnnouncementsComp = (props:IAnnouncementCompProps) => {

  const {
    inputRequest,
   // loading,
    //searchLoading,
    isSingleStockView,
    useStateData
  } = props;

   const dispatch = useDispatch<AppDispatch>();
    const { items: announcementsStateData, announcementReq:announcementReqStateData, loading: loadingStateData } = useSelector((state: RootState) => state.announcements);

   const { items: stocksData } = useSelector((state: RootState) => state.stocks);
   const [ annnouncementRequest, setAnnoncementRequest] = useState<IAnnouncementRequest>(inputRequest);
   const [ announcements, setAnnouncements] = useState<IAnnouncement[]>([]);
   const [ loading, setLoading] =useState<boolean>(false);
   const [ searchLoading, setSearchLoading] =useState<boolean>(false);
   
       //eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      if(useStateData){
        setLoading(true);
       if(announcementsStateData.length === 0){ //TODO: if results are 0 it will keep on executing
         dispatch(fetchAnnouncements(annnouncementRequest));
       }else{
        setAnnouncements(announcementsStateData);
        setAnnoncementRequest(announcementReqStateData);
        setLoading(false);
       }
      }else{
        loadAnnouncements();
      }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    },[props, dispatch, announcementsStateData,announcementReqStateData ]);

    const loadAnnouncements = async () => {
      setLoading(true);
      const announcements = await fetchAnnouncementsData(annnouncementRequest);
      setAnnouncements(announcements);
      setLoading(false);
    }

   const search = async () => {
    if(useStateData){
      dispatch(fetchAnnouncements(annnouncementRequest));
    }else{
      setSearchLoading(true);
      await loadAnnouncements();
      setSearchLoading(false);
    }
   }

   //TODO:implement reset for singleview aswell
   const resetFilter = async () => {
   await setAnnoncementRequest(initialState.announcementReq);
   dispatch(fetchAnnouncements(initialState.announcementReq));
   }

  const announcementsText = () => {
    let text = 'showing '+ announcements.length+' ';
      text += annnouncementRequest.impressions.length > 0 ? strJoin(annnouncementRequest.impressions): '';
      text += ' announcements ';
      text += annnouncementRequest.stockcodes.length > 0 ? 'for '+ strJoin(annnouncementRequest.stockcodes): '';
      text += ' ';
      text += annnouncementRequest.categories.length > 0 ? 'in categories '+strJoin(
        categories.filter(a => annnouncementRequest.categories.filter(b => b.toString() === a.code).length > 0)
        .map(a => {return a.name})
      ): '';
      text += ' ';

     if(annnouncementRequest.toDate.toDateString() === new Date().toDateString()){
        var days: number = Math.round((+annnouncementRequest.toDate - +annnouncementRequest.fromDate)/ 1000 / 60 / 60 / 24);
        text += 'for '+(days === 0 ? 'today': 'last '+ (days+1)+' days')+' ';
      }else{
        if(annnouncementRequest.fromDate.toDateString() === annnouncementRequest.toDate.toDateString())
        text += 'on '+annnouncementRequest.fromDate.toDateString();
      else
      text += 'from '+annnouncementRequest.fromDate.toDateString()+' to '+ annnouncementRequest.toDate.toDateString();
    }
    return text;
    }

    const onFilterStocksChange = (event:any, values:ILookup[]) => {
        setAnnoncementRequest({...annnouncementRequest, stockcodes: values.map(a=> a.code)});
    } 

    const onCategoriesChange = (event:any, values:ILookup[]) => {
        setAnnoncementRequest({...annnouncementRequest, categories: values.map(a => a.code as AnnouncementCategory)});
    } 

    const onImpressionsChange = (event:any, values:ILookup[]) => {
        setAnnoncementRequest({...annnouncementRequest, impressions: values.map(a=> a.code as AnnouncementImpression)});
    } 

    const onFromDataChange = (event:any, values:any) => {
        setAnnoncementRequest({...annnouncementRequest, fromDate: event.$d});
    }

    const onToDataChange = (event:any, values:any) => {
        setAnnoncementRequest({...annnouncementRequest, toDate: event.$d});
    }

    const isInitReq = (annnouncementRequest:IAnnouncementRequest) => {
      return annnouncementRequest.stockcodes.length === 0 && annnouncementRequest.categories.length === 0 &&
      annnouncementRequest.impressions.length === 1 && annnouncementRequest.impressions[0] === AnnouncementImpression.positive &&
      areDatesEqual(annnouncementRequest.fromDate,  initialState.announcementReq.fromDate) && areDatesEqual(annnouncementRequest.toDate, new Date());
    }
    return (
          
          <><div><Toaster/></div>
          <div className='page-header'>
          <div className="row">
                <div className="col-6 align-items-center">
                  <div>
                  <h6 className="mb-0">{props.isSingleStockView ? props.inputRequest.stockcodes[0]+"'s" :""} Announcements</h6></div>
                </div>
                <div className="col-6 text-end">
                 {(!props.isSingleStockView && !isInitReq(annnouncementRequest)) &&  <small><a onClick={resetFilter} className="link mr-8 pointer text-warning" href={undefined}>
                  reset filter</a></small>}
                  <button className="collapsed btn btn-success btn-sm mb-0" 
                  data-bs-target="#collapseOne" aria-controls="collapseOne"
                   data-bs-toggle="collapse" data-bs-auto-close="outside" aria-expanded="false">Filter&nbsp;
                   <span className="hide material-symbols-rounded">arrow_drop_up</span>
                    <span className="collapseshow material-symbols-rounded">arrow_drop_down</span>
                   </button>
                </div>
              </div>
             <div><small className='text-secondary'>{announcementsText()} <span className="text-secondary seperator"> &nbsp;| &nbsp;</span> <a className='link' href='#/alert'>set alerts</a></small></div>
          </div>
          <div className="accordion-item">
<div id="collapseOne"  className="accordion-collapse collapse" data-bs-parent="#accordionExample">
    <div className="accordion-body card">
  
  <ThemeProvider theme={muiTheme1}>
    <div className="row g-3">

      { !props.isSingleStockView && 
        <div className="col-sm-3">
     
        <Autocomplete
          value={stocksData.filter(a => annnouncementRequest.stockcodes.filter(b => b === a.code).length > 0)}
           size='small'
           onChange={onFilterStocksChange}
            multiple
            id=""
            options={stocksData}
            getOptionLabel={(option:IStock) => option.code+' - '+option.name}
            renderInput={(params) => (
              <TextField {...params} label="filter stocks" placeholder="search by scrip code or name" />
            )}
          />
         
        </div>
}
     
  <div className="col-sm-2">

  <Autocomplete
     value={categories.filter(a => annnouncementRequest.categories.filter(b => b === a.code).length > 0)}
     size='small'
      multiple
      id=""
      onChange={onCategoriesChange}
      options={categories}
      getOptionLabel={(option:ILookup) => option.name}
      renderInput={(params) => (
        <TextField {...params} label="category" placeholder="select categories" />
      )}
    />
  </div>
  <div className="col-sm-2">
  
  <Autocomplete
      size='small'
      multiple
      id=""
      value={impressions.filter(a => annnouncementRequest.impressions.filter(b => b === a.code).length > 0)}
      onChange={onImpressionsChange}
      options={impressions}
      getOptionLabel={(option:ILookup) => option.name}
      // defaultValue={[impressions[0]]}
      renderInput={(params) => (
        <TextField {...params} label="impression" placeholder="select impressions" />
      )}
    />
  </div>
  <div className="col-sm-2">
  <LocalizationProvider dateAdapter={AdapterDayjs}>
      <DatePicker
      maxDate={dayjs(new Date())}
      value={dayjs(annnouncementRequest.fromDate)}
      slotProps={{ textField: { size: 'small' } }}  onChange={onFromDataChange} label="from date" defaultValue={dayjs()}
      />
    </LocalizationProvider>
  </div>
  <div className="col-sm-2">
  <LocalizationProvider dateAdapter={AdapterDayjs}>
      <DatePicker value={dayjs(annnouncementRequest.toDate)} maxDate={dayjs(new Date())} slotProps={{ textField: { size: 'small' } }} onChange={onToDataChange} label="to date" defaultValue={dayjs()}/>
    </LocalizationProvider>
  </div>
  <div className="col-sm-1">
    <button onClick={search} type="button" className="d-flex btn btn-outline-success mb-0  btn-sm"> 
      {(loadingStateData || searchLoading) && <>Loading <CircularProgress className='spinner mt-1'/></>}
       {(!searchLoading && !loadingStateData) && <>Search</> } 
       </button>
  </div>
</div>
</ThemeProvider>
    </div>
</div>
</div>
<div className={(props.isSingleStockView ? "":"page-content")+" table-responsive bg-white"}>
    {!isMobile && <AnnouncementTableComponent rows={announcements}  isSingleStockView={props.isSingleStockView}
    // filterbyStock={props.filterbyStock}
    // announcementKey={props.announcementKey}
    />}

     {isMobile && <AnnouncementTableComponentMobile rows={announcements}  isSingleStockView={props.isSingleStockView}
    // filterbyStock={props.filterbyStock}
    // announcementKey={props.announcementKey}
    />}

    </div>
    <div className='text-center'>
      { loading && <CircularProgress className='spinner'/>}
    </div>
</>)
}

export default AnnouncementsComp;
