import './App.css';
import { createBrowserRouter, createHashRouter, RouterProvider } from 'react-router'
import AppLayout from "./components/layout/AppLayout"; 
import Announcements from './components/announcement/announcements';
import Announcement from './components/announcement/announcement';
import Alerts from './components/alert/alerts';
import React, { useEffect, useState } from 'react';
import Alert from './components/alert/alert';
import Stocks from './components/stock/stocks';
import Stock from './components/stock/stock';
import Notifications from './components/notification/notifications';
import SignIn from './components/user/signin';
import SignUp from './components/user/signup';
import Profile from './components/user/profile';
import ForgotPassword from './components/user/forgotpassword';
import HandleRedirect from './auth/handleGogleSigninRedirect';
import { auth } from './auth/firebase';
import { getRedirectResult, onAuthStateChanged } from 'firebase/auth';
import Plan from './components/plan/plan';
import Quotas from './components/user/quotas';
import AlertHistory from './components/alert/alerthistory';
import AuthProvider from './auth/authContext';
import { useDispatch } from 'react-redux';
import { AppDispatch } from './redux/store';
import { fetchStocks } from './redux/stock/stocksSlice';

