const router = createHashRouter([
//const router = createBrowserRouter([
  {
      path: "signin",
      element: <SignIn />,
  },
  {
    path: "signup",
    element: <SignUp />,
  },
  {
    path: "forgotpassword",
    element: <ForgotPassword />,
  },
    {
      path: "/",
      element: (
        <AuthProvider>
          <AppLayout />
        </AuthProvider>
      ),
      children: [
        {
          path: "/",
          element: <Announcements />,
        },
        {
          path: "announcements",
          element: <Announcements />
        },
        {
          path: "announcements/:announcementKey",
          element: <Announcement />
        },
        {
            path: "alerts",
            element: <Alerts />
          },
          {
            path: "alert",
            element: <Alert />
          },
          {
            path: "alert/:alertkey",
            element: <Alert />,
          },
          {
            path: "alerthistory",
            element: <AlertHistory />
          },
          {
            path: "alerthistory/:alertKey",
            element: <AlertHistory />
          },
          {
            path: "stocks",
            element: <Stocks />,
          },
          {
            path: "stocks/:stockCode",
            element: <Stock />,
          },
          {
            path: "notifications",
            element: <Notifications />,
          },
          {
            path: "profile",
            element: <Profile />,
          },
          {
            path: "plans",
            element: <Plan />,
          },
          {
            path: "quotas",
            element: <Quotas />,
          },
      ],
    }
  ]);
  
  
const App = () => {
 const dispatch = useDispatch<AppDispatch>();
  useEffect(() => {
    // Load global/shared data
    dispatch(fetchStocks());
  }, [dispatch]);

  return ( <RouterProvider router={router} />);
}

export default App;
