// features/stocks/stocksSlice.ts
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import axios from 'axios';
import { IStock } from '../../models/stock/stock';
import { backend } from '../../models/contants/contants';

interface StocksState {
  items: IStock[];
  loading: boolean;
  error: string | null;
}

const initialState: StocksState = {
  items: [],
  loading: false,
  error: null,
};

// Async thunk to fetch stocks
export const fetchStocks = createAsyncThunk<IStock[], void>(
  'stocks/fetchStocks',
  async (_, { rejectWithValue }) => {
    try {
      const response = await axios.get(`${backend}stocks?limit=10000`, {
        headers: {
          authorization: 'your token comes here',
        },
      });
      return response.data;
    } catch (err: any) {
      return rejectWithValue(err.message);
    }
  }
);

const stocksSlice = createSlice({
  name: 'stocks',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchStocks.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchStocks.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload;
      })
      .addCase(fetchStocks.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      });
  },
});

export default stocksSlice.reducer;
