import React, {useEffect, useRef, useState} from 'react';
import toast, { Toaster } from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';
import { isNullEmptyOrWhitespace, validateEmail } from '../../utility/utility';
import { auth } from '../../auth/firebase';
import { createUserWithEmailAndPassword, getAuth, getRedirectResult, GoogleAuthProvider, sendEmailVerification, signInWithPopup, signInWithRedirect, updateProfile } from 'firebase/auth';
import { GoogleIcon } from '../common/utilitycomp';
import { CircularProgress } from '@mui/material';

const SignUp = () => {
   const [signupProgress, setSignupProgress] = useState(false);
       const [googleSignupProgress, setGoogleSignupProgress] = useState(false);

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [reenterPassword, setReenterPassword] = useState('');
  const [agreeTerms, setAgreetTerms] = useState(false);

  const nameInputRef = useRef<HTMLInputElement>(null);
  const emailInputRef = useRef<HTMLInputElement>(null);
  const passwordInputRef = useRef<HTMLInputElement>(null);
  const reeneterPasswordInputRef = useRef<HTMLInputElement>(null);

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
   getRedirectResult(auth).then((res:any) => {
    console.log('signp redirect res',res);
   })
        
    },[]);

    const onSignUp = async () => {
      if(validate()){
         setSignupProgress(true);
        await createUserWithEmailAndPassword(auth, email, password)
        .then((userCredential:any) => {
            // Signed in
            const user = userCredential.user;
            console.log(user);
            updateProfile(user,{displayName:name,photoURL:''});
            sendEmailVerification(user);
            alert('Signup successful. Please verify the verification link sent to email and proceed to signin.')
            navigate("/signin")
            // ...
        })
        .catch((error:any) => {
          alert(error.message.replace("Firebase: ",""));
            const errorCode = error.code;
            const errorMessage = error.message;
            console.log(errorCode, errorMessage);
            // ..
        }).finally(()=>{
           setSignupProgress(false);
        });
      }
    }

 //  const signInWithGooglePopup = () => signInWithPopup(auth, provider);

    const onSignUpUsingGoogle = async () => {
       setGoogleSignupProgress(true);
      const provider = new GoogleAuthProvider();
      // whenever a user interacts with the provider, we force them to select an account
      provider.setCustomParameters({   
          prompt : "select_account "
      });
     //var res =  await signInWithRedirect(auth, provider);
     await signInWithPopup(auth, provider).then((res:any)=>{
      navigate("/");
      console.log('signup',res);
     });
    setGoogleSignupProgress(false);
} 

    const validate = () => {
    let isValid = true;
    toast.dismiss();

      if(isNullEmptyOrWhitespace(name)){
        toast.error('Enter name');
        if(isValid)
        nameInputRef.current?.focus();
        isValid = false;
      }

      if(isNullEmptyOrWhitespace(email)){
        toast.error('Enter email');
        if(isValid)
          emailInputRef.current?.focus();
        isValid = false;
      }else if(!validateEmail(email)){
        if(isValid)
          emailInputRef.current?.focus();
        toast.error('Enter valid email');
        isValid = false;
      }

      if(isNullEmptyOrWhitespace(password)){
        if(isValid)
          passwordInputRef.current?.focus();
        toast.error('Enter password');
        isValid = false;
      }

      if(isNullEmptyOrWhitespace(reenterPassword)){
        if(isValid)
          reeneterPasswordInputRef.current?.focus();
        toast.error('Re enter passoword');
        isValid = false;
      }

      if(password !== reenterPassword){
        if(isValid)
          passwordInputRef.current?.focus();
        toast.error('Passwords do not match');
        isValid = false;
      }

      if(!agreeTerms){
        toast.error('Check agree to terms & conditions');
        isValid = false;
      }

      return isValid;
  };
    const navigate = useNavigate();
    return (
        <div>
         <Toaster position="bottom-center" reverseOrder={false}/>
          <div>
        <div className="container">
          <div className="row">
            <div className="col-xl-3 col-lg-4"></div>
            <div className="col-xl-6 col-lg-4">
                            <div className='mb-4 text-center mt-50'>
               <img height="40" className="navbar-brand-img"  alt="img" 
                  src="media/brandlogo.png"/>
             </div>
              <div className="card">
                <div className="card-header">
                  <h4 className="font-weight-bold">Sign Up</h4>
                  <p className="mb-0">Enter your email and password to register</p>
                </div>
                <div className="card-body">
                  <form role="form">
                    <div className="input-group input-group-outline mb-3">
                      <label className="form-label">Name</label>
                      <input ref={nameInputRef} value={name} onChange={(e) =>{setName(e.target.value);}} type="text" className="form-control"/>
                    </div>
                    <div className="input-group input-group-outline mb-3">
                      <label className="form-label">Email</label>
                      <input ref={emailInputRef} value={email} onChange={(e) =>{setEmail(e.target.value);}} type="email" className="form-control"/>
                    </div>
                    <div className="input-group input-group-outline mb-3">
                      <label className="form-label">Password</label>
                      <input ref={passwordInputRef} value={password} onChange={(e) =>{setPassword(e.target.value);}} type="password" className="form-control"/>
                    </div>
                    <div className="input-group input-group-outline mb-3">
                      <label className="form-label">Re enter password</label>
                      <input ref={reeneterPasswordInputRef} value={reenterPassword} onChange={(e) =>{setReenterPassword(e.target.value);}} type="password" className="form-control"/>
                    </div>
                    <div className="">
                      <input checked={agreeTerms} onChange={(e) => {setAgreetTerms(e.target.checked)}} type="checkbox" value="" id="flexCheckDefault" />
                      <label>
                        I agree the <a href="javascript:;" className="text-dark font-weight-bold">Terms and Conditions</a>
                      </label>
                    </div>
                    <div className="text-center">
                      <button onClick={() => onSignUp()} type="button" className="btn btn-lg btn-success btn-lg w-100 mt-1">Sign up
 {signupProgress && <CircularProgress className='spinnerbtn'/>}

                      </button>
                      <button onClick={() => onSignUpUsingGoogle()} type="button" className="btn btn-lg btn-outline-secondary btn-lg w-100 mb-0">
                      {GoogleIcon} &nbsp;Sign up using Google
                       {googleSignupProgress && <CircularProgress style={{marginBottom:-2}} className='spinner'/>}
                      </button>
                    </div>
                  </form>
                </div>
                <div className="card-footer text-center pt-0 px-lg-2 px-1">
                  <p className="mb-2 text-sm mx-auto">
                    Already have an account?
                    <a href="#/signin" className="link font-weight-bold">&nbsp; sign in</a>
                    <span className='text-secondary seperator'> &nbsp;| &nbsp;</span>
                    <a className="link font-weight-bold" rel="noreferrer" 
                  href="#/" >home</a>
                  </p>
                </div>
              </div>
            </div>
            <div className="col-xl-3 col-lg-4"></div>
          </div>
        </div>
      </div>
      </div>
    )
}

export default SignUp;

function signInWithGooglePopup() {
  throw new Error('Function not implemented.');
}
